eA?art_wr_of_bytesC1?~~~~~~~~~~~~~~~C46Stdlib;setoid_ring6Ncring;eq_notationC46Stdlib;setoid_ring6Ncring>ring_mult_compK46Stdlib9micromega5Tauto8GFormula06C56Stdlib6ZArith6BinInt1Z3oppC46Stdlib;setoid_ring>Ncring_initial4ZopsC46Stdlib;setoid_ring>Ncring_initial2ZrI4ELinuxProcessSemantics?LinuxProcessSem5State5Model00K46Stdlib9micromega=RingMicromega3Op206C59OSSVerify5KrLib7Mh_01456NarInv5rn_arC1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib7Mh_0089:HeapIfaceA5ar_fsC1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib7Mh_01456NarInv8rn_kbaseC1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib7Mh_01456NarInv7rn_parrC1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib7Mh_01456NarInv5rn_l2C1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib7Mh_01456NarInv6rn_blkC1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib7Mh_01456NarInv7rn_dtlsC1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib7Mh_01456NarInv8art_objsC1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib7Mh_0089:HeapIfaceA8FS_BYTESC1?~~~~~~~~~~~~~~~c49OSSVerify5KrLib<NarWrapFreeR>art_fpl_bundleC1?~~~~~~~~~~~~~~~C49OSSVerify5KrLib:NarInvFree<art_free_fplC1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib7Mh_0279<NarWrapFreeC@art_lazy_ok_stepC1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib7Mh_0145>NarInvFreePure;art_gs_freeC1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib7Mh_01099ArtBridge<in_ev_rangesC1?~~~~~~~~~~~~~~~". Local Ltac lia := L5FastLiaT.plia1.
Open Scope Z_scope.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

#[local] Abbreviation ASEGS := Asan.M.loaded_segments.
#[local] Abbreviation cellA := (cell Asan.M.loaded_segments).
#[local] Abbreviation wrA := (wr Asan.M.loaded_segments).
#[local] Notation "'U' r" := (bv_unsigned r) (at level 10, r at level 9).

Section Post.
Variable FSG : Type.

Definition art_rcy_post (rn : art_run) (Gq : art_gs FSG) (LB' : list (Z * Z)) (Sp : Z) (M10 M' : word -> option byte) (G' : art_gs FSG) (evs : list aev) : Prop :=
  art_alloc_rep FSG rn G' LB' M' /\ art_rt_ghost FSG rn G' M'
  /\ g_log FSG G' = g_log FSG Gq ++ evs /\ g_fs FSG G' = g_fs FSG Gq /\ g_depot FSG G' = g_depot FSG Gq /\ g_sec_committed FSG G' = g_sec_committed FSG Gq
  /\ (forall ev, In ev evs -> (exists a l, ev = AMadvise a l) \/ (exists a l, ev = AMunmap a l) \/ (exists a l, ev = AMmapFixed a l))      (* [comment removed for export] *)
  /\ art_cost_sum evs = art_primsum (g_cls FSG G') - art_primsum (g_cls FSG Gq)                                                             (* [comment removed for export] *)
  /\ (forall c, cl_mu (g_cls FSG G' c) = cl_mu (g_cls FSG Gq c) /\ cl_mfa (g_cls FSG Gq c) <= cl_mfa (g_cls FSG G' c))                       (* [comment removed for export] *)
  /\ (length (art_live (g_log FSG G')) <= length (art_live (g_log FSG Gq)))%nat /\ (length (g_sec FSG G') <= length (g_sec FSG Gq))%nat
  /\ (forall c, 1 <= c <= 30 ->
        Z.of_nat (length (cl_free (g_cls FSG G' c))) + Z.of_nat (length (cl_cache (g_cls FSG G' c))) + art_nq (g_qt FSG G' ++ g_qg FSG G')
        <= Z.of_nat (length (cl_free (g_cls FSG Gq c))) + Z.of_nat (length (cl_cache (g_cls FSG Gq c))) + art_nq (g_qt FSG Gq ++ g_qg FSG Gq))
  /\ art_nq (g_qt FSG G' ++ g_qg FSG G') <= art_nq (g_qt FSG Gq ++ g_qg FSG Gq)
  /\ g_qt FSG G' = [] /\ (exists kk : nat, g_qg FSG G' = skipn kk (g_qg FSG Gq ++ g_qt FSG Gq))                             (* [comment removed for export] *)
  /\ wrA M' (Sp - 4096) 4096
  /\ exists FPR : Z -> Prop,
       (forall x : word, ~ FPR (U x) -> M' x = M10 x)
       /\ (forall z, in_ev_ranges evs z -> FPR z)
       /\ (forall b0 a, In b0 LB' -> (fst b0 <= a < fst b0 + snd b0 \/ in_shadow_of (fst b0) (snd b0) a) -> ~ FPR a)
       /\ (forall a, rn_HI rn <= a < 2 ^ 64 -> ~ (Sp - 4096 <= a < Sp) -> ~ FPR a)
       /\ (forall a, 0x10000 <= a < 0x6b6000 -> ~ art_zone_statics a -> ~ FPR a)
       /\ (forall a, ar_fs (rn_ar rn) <= a < ar_fs (rn_ar rn) + FS_BYTES -> ~ FPR a)
       /\ (forall a, rn_dtls rn <= a < rn_dtls rn + 4096 -> ~ FPR a)
       /\ (forall a, rn_t rn + 72 <= a < rn_t rn + 80 -> ~ FPR a)
       /\ (forall lo len a, 0 <= lo -> 0 < len -> lo + len <= 2 ^ 47 -> (lo + len <= rn_kbase rn \/ rn_kbase rn + 0x2000011000 <= lo) ->
             (forall p, In p (art_live (g_log FSG Gq)) -> apart (fst p) (snd p) lo len) -> HeapIfaceA.S lo <= a <= HeapIfaceA.S (lo + len - 1) -> ~ FPR a).
End Post.

